using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Service registration ---
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseFunctionInvocation(options => options.MaximumIterationsPerRequest = 10)
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// --- Tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Agent setup ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research agent that searches the web and takes notes to produce a summary.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- Run the agent ---
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
Console.WriteLine($"🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"""
    Research the following topic thoroughly by searching the web multiple times with different queries.
    Save important findings as notes, then produce a comprehensive summary at the end.

    Topic: {topic}

    Steps:
    1. Search the web with 2-3 different queries related to the topic
    2. Save key findings as notes with descriptive titles
    3. Review your notes and write a well-structured summary

    Provide the final summary as your response.
    """,
    session);

Console.WriteLine("📋 Research Summary:");
Console.WriteLine(new string('─', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 60));

if (_notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes collected ({_notes.Count}):");
    foreach (var (title, _) in _notes)
    {
        Console.WriteLine($"  • {title}");
    }
}

return;

// ────────────────────────────────────────────────────────────
// Tool implementations
// ────────────────────────────────────────────────────────────

[Description("Search the web for information on a given query. Returns relevant search results.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    Console.WriteLine($"  🌐 Searching: \"{query}\"");
    return $"""
        Search results for "{query}":

        1. [Research Paper] Recent developments show significant progress in {query}.
           Key findings include improved methodologies and novel applications.
           Source: arxiv.org - Published 2024

        2. [News Article] Industry leaders report breakthroughs related to {query}.
           Multiple organizations have announced new initiatives in this space.
           Source: techreview.com - Updated June 2024

        3. [Wikipedia] {query} encompasses a broad field of study with applications
           in technology, science, and industry. Recent trends indicate growing
           investment and interest from both academia and the private sector.
           Source: wikipedia.org
        """;
}

static readonly List<(string Title, string Content)> _notes = [];

[Description("Save a research note with a title and content for later reference.")]
static string SaveNote(
    [Description("A short descriptive title for the note")] string title,
    [Description("The content/body of the note")] string content)
{
    _notes.Add((title, content));
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note '{title}' saved successfully.";
}

[Description("Retrieve all previously saved research notes.")]
static string GetNotes()
{
    if (_notes.Count == 0)
        return "No notes have been saved yet.";

    var result = string.Join("\n\n", _notes.Select((n, i) =>
        $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    return result;
}

