 using System.ComponentModel;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;
 using OpenAI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run this app.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // --- Service registration ---
 var services = new ServiceCollection();
 services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

 services.AddChatClient(sp =>
         (IChatClient)new OpenAIClient(apiKey).GetChatClient(modelId))
     .UseFunctionInvocation(configure: fic => fic.MaximumIterationsPerRequest = 10);

 var sp = services.BuildServiceProvider();
 var chatClient = sp.GetRequiredService<IChatClient>();

 // --- Tools ---
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(WebSearch),
     AIFunctionFactory.Create(SaveNote),
     AIFunctionFactory.Create(GetNotes),
 };

 // --- Agent setup ---
 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An AI research agent that searches the web and takes notes to produce a summary.",
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
             Tools = [.. tools],
         },
     });

 // --- Run the agent ---
 var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
 Console.WriteLine($"🔍 Researching: {topic}\n");

 var session = await agent.CreateSessionAsync();
 var response = await agent.RunAsync(
     $"""
     Research the following topic thoroughly by searching the web multiple times with different queries.
     Save important findings as notes, then produce a comprehensive summary at the end.

     Topic: {topic}

     Steps:
     1. Search the web with 2-3 different queries related to the topic
     2. Save key findings as notes with descriptive titles
     3. Review your notes and write a well-structured summary

     Provide the final summary as your response.
     """,
     session);

 Console.WriteLine("📋 Research Summary:");
 Console.WriteLine(new string('─', 60));
 Console.WriteLine(response.Text);
 Console.WriteLine(new string('─', 60));

 if (Notebook.Notes.Count > 0)
 {
     Console.WriteLine($"\n📝 Notes collected ({Notebook.Notes.Count}):");
     foreach (var (title, _) in Notebook.Notes)
     {
         Console.WriteLine($"  • {title}");
     }
 }

 return;

